ValidationRule.errorConditionFormula:
AND(
    $Profile.Name = "Gerente de Projetos",

    OR(
        AND(
            OR(
                ISCHANGED(Inicio_da_atividade_1__c),
                ISCHANGED(Fim_da_atividade_1__c)
            ),

            NOT(ISBLANK(Executor_da_atividade_1__c)),

            NOT(
                CONTAINS(
                    LOWER(Executor_da_atividade_1__r.Title),
                    "projeto"
                )
            )
        ),

        AND(
            OR(
                ISCHANGED(Inicio_da_atividade_2__c),
                ISCHANGED(Fim_da_atividade_2__c)
            ),

            NOT(ISBLANK(Executor_da_atividade_2__c)),

            NOT(
                CONTAINS(
                    LOWER(Executor_da_atividade_2__r.Title),
                    "projeto"
                )
            )
        ),

        AND(
            OR(
                ISCHANGED(Inicio_da_atividade_3__c),
                ISCHANGED(Fim_da_atividade_3__c)
            ),

            NOT(ISBLANK(Executor_da_atividade_3__c)),

            NOT(
                CONTAINS(
                    LOWER(Executor_da_atividade_3__r.Title),
                    "projeto"
                )
            )
        )
    )
)
